335	func printProposalContext(cmd *cobra.Command, facts []factRecord, p factProposal) {
336		if i := indexOfFact(facts, p.CandidateID); i >= 0 {
337			fmt.Fprintf(cmd.OutOrStdout(), "  candidate: %s\n", truncateString(facts[i].Text, 100))
338		}
339		if i := indexOfFact(facts, p.TargetID); i >= 0 {
340			fmt.Fprintf(cmd.OutOrStdout(), "  target:    %s\n", truncateString(facts[i].Text, 100))
341		}
342	}
