350			strategy string
351			jsonOut  bool
352		)
353		cmd := &cobra.Command{
354			Use:   "promote",
355			Short: "Carry a branch's active facts into another branch",
356			Args:  cobra.NoArgs,
357			RunE: func(cmd *cobra.Command, args []string) error {
358				if strings.TrimSpace(from) == "" {
359					return fmt.Errorf("--from <branch> is required")
360				}
361				switch strategy {
362				case "keep-both", "prefer-source", "prefer-target":
363				default:
364					return fmt.Errorf("--strategy must be keep-both, prefer-source, or prefer-target")
365				}
366				repoDir, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
367				if err != nil {
368					return err
369				}
370				target := into
371				if strings.TrimSpace(target) == "" {
372					if current, gitErr := gitScalar(cmd.Context(), opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
373						target = strings.TrimSpace(current)
374					}
375				}
376				if strings.TrimSpace(target) == "" {
377					return fmt.Errorf("--into <branch> is required (could not detect current branch)")
378				}
379				if target == from {
380					return fmt.Errorf("--from and --into must differ")
381				}
382				if err := validateFactsPromoteEndpoints(cmd.Context(), opts, repoDir, brainDir, from, target); err != nil {
383					return err
384				}
385				return runFactsPromote(cmd, opts, brainDir, from, target, strategy, jsonOut)
386			},
387		}
388		cmd.Flags().StringVar(&from, "from", "", "Source branch to promote facts from (required)")
389		cmd.Flags().StringVar(&into, "into", "", "Target branch (default: current branch)")
390		cmd.Flags().StringVar(&strategy, "strategy", "keep-both", "Conflict strategy: keep-both, prefer-source, or prefer-target")
391		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the result summary as JSON")
392		return cmd
393	}
