41	// resolveFactsTarget resolves the repo, brain directory, and the branch facts
42	// are scoped to (the live git branch unless overridden). It is shared by the
43	// fact read/write commands.
44	func resolveFactsTarget(ctx context.Context, opts Options, target, branchOverride string) (repoDir, brainDir, branch string, err error) {
45		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
46		if err != nil {
47			return "", "", "", err
48		}
49		if !local {
50			return "", "", "", fmt.Errorf("memories require a local repository path: %s", target)
51		}
52		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
53		if err != nil {
54			return "", "", "", err
55		}
56		branch = strings.TrimSpace(branchOverride)
57		if branch == "" {
58			if current, gitErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
59				branch = strings.TrimSpace(current)
60			}
61		}
62		if branch == "" {
63			branch = distillDefaultBranch
64		}
65		return repoDir, storage.BrainDir, branch, nil
66	}
