101		// `doctor` and `config` are PRESENT. They were hidden here as plugin
102		// plumbing, and this list pinned that -- while the README documented
103		// doctor's exit-code contract in its own section and scripts/install.sh ran
104		// both and closed by telling the reader to re-run `entire brain doctor`.
105		// TestDocumentedCommandsAreDiscoverable now holds the general rule; this is
106		// the direct assertion for the two that were wrong.
107		for _, want := range []string{"  doctor ", "  config "} {
108			if !strings.Contains(out, want) {
109				t.Fatalf("root output should list %q (the docs tell users to run it):\n%s", want, out)
110			}
111		}
112		// Absent from top-level help: the dropped completion generator; removed
113		// redundant aliases; and the build stages that now live under `refresh`
114		// (sessions, index, seed).
115		for _, absent := range []string{
116			"  completion ", "  bench ",
117			"  context ", "  impact ", "  changes ",
118			"  tests ", "  routes ", "  tools ", "  workflows ",
119			"  index ", "  seed ", "  sessions ", "  history-index ",
120		} {
121			if strings.Contains(out, "\n"+absent) {
122				t.Fatalf("root output should not list %q:\n%s", absent, out)
123			}
124		}
125	}
