127	func TestRootHelpAllShowsDeveloperCommands(t *testing.T) {
128		for _, args := range [][]string{{"--help-all"}, {"--help-all", "--help"}} {
129			root := NewRootCommand(Options{Version: "test"})
130			out, err := execute(t, root, args...)
131			if err != nil {
132				t.Fatalf("%v: %v\n%s", args, err, out)
133			}
134			// Include previously hidden machine surfaces as well as the newly
135			// hidden developer paths. All-help must not mutate dispatch visibility.
136			for _, path := range []string{"bench", "bench semantic", "bench scale", "facts eval", "facts eval-gen", "facts eval-compare", "facts reclassify", "inspect graph-schema", "docs formats", "history-eval", "hook", "review"} {
137				if !strings.Contains(out, "\n  "+path+" ") {
138					t.Errorf("all-help missing %q", path)
139				}
140				c, _, err := root.Find(strings.Fields(path))
141				// Bench children remain visible within the hidden family so
142				// explicit `bench --help` can describe its subcommands.
143				wantHidden := path != "bench semantic" && path != "bench scale"
144				if err != nil || c.Hidden != wantHidden {
145					t.Errorf("%q hidden should remain %v after all-help: %v", path, wantHidden, err)
146				}
147			}
148		}
149		for family, hidden := range map[string][]string{
150			"facts":   {"eval", "eval-gen", "eval-compare", "reclassify"},
151			"inspect": {"graph-schema"},
152			"docs":    {"formats"},
153		} {
154			out, err := execute(t, NewRootCommand(Options{Version: "test"}), family, "--help")
155			if err != nil {
156				t.Fatal(err)
157			}
158			for _, name := range hidden {
159				if strings.Contains(out, "\n  "+name+" ") {
160					t.Errorf("%s --help lists developer command %q", family, name)
161				}
162			}
163		}
164	}
165	
166	func TestBenchmarkHelpKeepsHiddenFamilyDiscoverable(t *testing.T) {
167		root := NewRootCommand(Options{Version: "test"})
168		out, err := execute(t, root, "bench", "--help")
169		if err != nil {
170			t.Fatal(err)
171		}
172		for _, want := range []string{"entire-brain bench [command]", "Available Commands:", "\n  semantic ", "\n  scale "} {
173			if !strings.Contains(out, want) {
174				t.Errorf("bench help missing %q:\n%s", want, out)
175			}
176		}
177		bench, _, err := root.Find([]string{"bench"})
178		if err != nil || !bench.Hidden {
179			t.Fatalf("benchmark family should remain hidden: %v", err)
180		}
181		for _, child := range bench.Commands() {
182			if child.Hidden {
183				t.Errorf("bench child %q should be visible in contextual help", child.Name())
184			}
185		}
186		out, err = execute(t, NewRootCommand(Options{Version: "test"}), "--help")
187		if err != nil {
188			t.Fatal(err)
189		}
190		for _, path := range []string{"bench", "bench semantic", "bench scale"} {
191			if strings.Contains(out, "\n  "+path+" ") {
192				t.Errorf("default root help should not list %q:\n%s", path, out)
193			}
194		}
